merge_cells &lt;- function(record, keys) {
  record |&gt; group_by(across(all_of(keys))) |&gt;
    summarise(across(c(G, starts_with(c("S1_", "S2_"))), sum), .groups = "drop")
}

cell_moments &lt;- function(record, u_cols, strata) {
  K &lt;- length(u_cols)
  S2_name &lt;- \(i, j) paste0("S2_", u_cols[min(i, j)], "_", u_cols[max(i, j)])
  record |&gt;
    group_by(across(all_of(strata))) |&gt; mutate(w = sum(G)) |&gt; ungroup() |&gt;
    mutate(w = w / sum(G),                                                  # stratum share w_h
           u_bar = pmap(pick(G, starts_with("S1_", ignore.case = FALSE)), \(G, ...) set_names(c(...) / G, u_cols)),
           V = pmap(pick(everything()), \(...) {
             r &lt;- list(...)
             S2 &lt;- outer(1:K, 1:K, Vectorize(\(i, j) r[[S2_name(i, j)]]))
             (S2 / r$G - tcrossprod(r$u_bar)) / r$G                         # Cov of the cell mean
           }))
}

grad_complex_step &lt;- function(f, theta, kappa = 1e-20) {
  map_dbl(seq_along(theta), \(l) Im(f(theta + 1i * kappa * (seq_along(theta) == l))) / kappa)
}

delta_method &lt;- function(cells, g) {
  U &lt;- do.call(rbind, cells$u_bar)                                          # one row per cell
  f &lt;- \(theta) g(matrix(theta, nrow(U), byrow = TRUE, dimnames = dimnames(U)), cells)
  theta &lt;- as.vector(t(U))
  grad_g &lt;- grad_complex_step(f, theta)
  V &lt;- as.matrix(Matrix::bdiag(cells$V))
  c(estimate = Re(f(theta)), se = sqrt(drop(t(grad_g) %*% V %*% grad_g)))
}

arm_mean &lt;- function(U, cells, z) colSums(cells$w[cells$Z == z] * U[cells$Z == z, , drop = FALSE])
g_itt &lt;- function(U, cells) {
  mu_1 &lt;- arm_mean(U, cells, 1); mu_0 &lt;- arm_mean(U, cells, 0)
  mu_1[["Y"]] / mu_1[["n"]] - mu_0[["Y"]] / mu_0[["n"]]
}
g_late &lt;- function(U, cells) {
  mu_1 &lt;- arm_mean(U, cells, 1); mu_0 &lt;- arm_mean(U, cells, 0)
  (mu_1[["Y"]] / mu_1[["n"]] - mu_0[["Y"]] / mu_0[["n"]]) /
    (mu_1[["nT"]] / mu_1[["n"]] - mu_0[["nT"]] / mu_0[["n"]])
}
g_ratio &lt;- function(U, cells) {
  mu_1 &lt;- arm_mean(U, cells, 1); mu_0 &lt;- arm_mean(U, cells, 0)
  mu_1[["N"]] / mu_1[["D"]] - mu_0[["N"]] / mu_0[["D"]]
}

Many covariates
The full model has five covariates and five outcome columns, so \(u_a\) has \(d o + 2 d^2 =\) 102 entries. Writing one dplyr column per entry would work, but it is tedious, so we build \(u_a\) with a loop in C++ using Rcpp. The loop visits each row once and adds its products into its account’s sums. This is the only step that visits every row. Account ids run from 1 to the number of accounts, so they index the output directly.


Code
#include &lt;Rcpp.h&gt;
using namespace Rcpp;

// Profile rows to account summaries u_a = (vec S^Y, vec S, vec S^T) in one pass, with R = (1, x) and Y the outcome columns.
// [[Rcpp::export]]
NumericMatrix account_summaries(IntegerVector account, NumericMatrix R, NumericVector T, NumericMatrix Y, int n_accounts) {
  int n = R.nrow(), d = R.ncol(), o = Y.ncol();
  NumericMatrix u(n_accounts, d * o + 2 * d * d);
  for (int i = 0; i &lt; n; i++) {
    int a = account[i] - 1;
    for (int l = 0; l &lt; o; l++) for (int j = 0; j &lt; d; j++) u(a, l * d + j) += R(i, j) * Y(i, l);     // S^Y
    for (int m = 0; m &lt; d; m++) for (int j = 0; j &lt; d; j++) {
      double rr = R(i, j) * R(i, m);
      u(a, d * o + m * d + j) += rr;                                                                // S
      u(a, d * o + d * d + m * d + j) += T[i] * rr;                                                 // S^T
    }
  }
  return u;
}




